const input=$json??{}; const event=input.event??input;
const dealId=event.deal_id??event.dealId, leadId=event.lead_id??event.leadId, propertyId=event.property_id??event.propertyId;
const response=event.seller_response??event.inbound_response??event.response;
const responseType=String(event.response_type??event.classification??'').toLowerCase();
const status=String(event.status??'').toLowerCase();
const dnc=Boolean(event.dnc??event.do_not_contact), blockers=Array.isArray(event.blockers)?event.blockers:[];
const attempts=Number(event.attempts??event.outreach_attempts??0), maxAttempts=Number(event.max_attempts??3);
const consent=event.followup_consent===false?false:true;
const sellerOptOut=Boolean(event.opt_out||event.unsubscribe||event.stop);
const baseKey=event.idempotency_key??[dealId,leadId,propertyId,'seller-followup'].filter(Boolean).join(':');
const decisionKey=baseKey+':eligibility:'+attempts;
let route='WF-352',decision='followup_not_eligible',reason='unclassified';
if(dnc||sellerOptOut){route='WF-126';decision='dnc_hard_stop';reason='seller_opt_out_or_dnc';}
else if(blockers.length){route='WF-126';decision='blocked';reason='operational_blocker';}
else if(!dealId||!leadId||!propertyId||!baseKey){route='WF-356';decision='missing_identity_or_idempotency';reason='required_identity_missing';}
else if(response){route='WF-342';decision='seller_response_received';reason='inbound_response_priority';}
else if(responseType==='not_interested'||responseType==='rejected'){route='WF-345';decision='reengagement_eligible';reason='seller_rejection';}
else if(attempts>=maxAttempts){route='WF-126';decision='human_review_max_attempts';reason='outreach_limit_reached';}
else if(consent&&['followup_due','timeout','no_response',''].includes(status)){route='WF-346';decision='reengagement_eligible';reason='followup_due_or_timeout';}
else {route='WF-352';decision='followup_not_eligible';reason='waiting_or_unresolved_state';}
return [{json:{...event,workflow:'WF-357',decision,reason,route,deal_id:dealId,lead_id:leadId,property_id:propertyId,attempts,max_attempts:maxAttempts,followup_consent:consent,idempotency_key:baseKey,decision_idempotency_key:decisionKey,audit_event:'final_followup_eligibility_reengagement_decision'}}];
